-- ============================================================================
-- seed_etl_run_config_TTF.sql  (TTF step-driver package)
--
-- Seeds COMMON.ETL_RUN_CONFIG_TBL for workflow wf_TTF_Stage_Load: one row
-- per driver row (STEP_NO = 0, IS_DRIVER = 'Y') + every transform step +
-- every publish branch. All IS_RUN_ENABLED = 'Y' (everything runs).
-- The DELETE below removes TTF rows only (by workflow name), so re-running
-- this seed is safe. Run it in the COMMON schema (MDM_ETL_COMMON.COMMON).
-- NOTE: IS_DEPENDENT / DEPENDENT_ON / WORK_TABLES_PRODUCED are informational
-- for a driver run -- gating is by IS_RUN_ENABLED only. The driver does NOT
-- validate flag consistency: disabling a producer while a consumer stays
-- enabled fails loudly on the missing input table (step 5 drops ALL work
-- tables regardless of flags).
-- ============================================================================

DELETE FROM ETL_RUN_CONFIG_TBL WHERE WORKFLOW_NAME = 'wf_TTF_Stage_Load';


-- 29 rows: 4 driver rows + 12 steps + 13 publish branches.
